mapper.select:
SELECT COUNT(*)
FROM TEAM_MEMBERS
WHERE team_id = #{teamId}

SELECT COUNT(*)
FROM TEAM_MEMBERS
WHERE team_id = #{teamId}
  AND user_id = #{userId}

SELECT t.id AS team_pk_id, t.team_id, t.team_name, t.capacity, t.invite_code, t.team_goal, t.king_id, t.created_at AS team_created_at, t.updated_at AS team_updated_at,
k.id AS king_pk_id, k.user_id AS king_user_id, k.nick_name AS king_nickname, k.profile_img AS king_profile_img,
m.id AS member_pk_id, m.user_id AS member_user_id, m.nick_name AS member_nickname, m.profile_img AS member_profile_img FROM TEAMS t JOIN USERS k ON t.king_id = k.id LEFT JOIN TEAM_MEMBERS tm ON t.id = tm.team_id LEFT JOIN USERS m ON tm.user_id = m.id WHERE t.id = #{id}
